import sys

def main():
    content = sys.stdin.read()
    if not content:
        return
    lines = [line.strip() for line in content.strip().split('\n')]
    idx = 0
    def readline():
        nonlocal idx
        if idx < len(lines):
            val = lines[idx]
            idx += 1
            return val
        return ''
    N = int(readline())
    out = []
    for _ in range(N):
        f = list(map(int, readline().split()))
        s = list(map(int, readline().split()))
        if f[0] == 0 and f[1] == 0 and s[0] == 0 and s[1] == 0:
            out.append('0')
        elif f[0] + f[1] + s[0] + s[1] == 4:
            out.append('2')
        else:
            out.append('1')
    sys.stdout.write('\n'.join(out))

if __name__ == "__main__":
    main()

